func (q *Queries) ListTargetAlertOverrides(ctx context.Context, arg ListTargetAlertOverridesParams) ([]AlertOverride, error) {
	rows, err := q.db.QueryContext(ctx, listTargetAlertOverrides, arg.ServerID, arg.AppID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AlertOverride{}
	for rows.Next() {
		var i AlertOverride
		if err := rows.Scan(
			&i.RuleID,
			&i.ServerID,
			&i.AppID,
			&i.Disabled,
			&i.Threshold,
			&i.DurationMinutes,
			&i.ChannelIds,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

