const upsertAlertOverride = `-- name: UpsertAlertOverride :exec
INSERT INTO alert_overrides (rule_id, server_id, app_id, disabled, threshold, duration_minutes, channel_ids)
VALUES (?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (rule_id, server_id, app_id) DO UPDATE
SET disabled = excluded.disabled, threshold = excluded.threshold,
    duration_minutes = excluded.duration_minutes, channel_ids = excluded.channel_ids
`

type UpsertAlertOverrideParams struct {
	RuleID          string
	ServerID        string
	AppID           string
	Disabled        bool
	Threshold       *float64
	DurationMinutes *int64
	ChannelIds      *string
}

func (q *Queries) UpsertAlertOverride(ctx context.Context, arg UpsertAlertOverrideParams) error {
	_, err := q.db.ExecContext(ctx, upsertAlertOverride,
		arg.RuleID,
		arg.ServerID,
		arg.AppID,
		arg.Disabled,
		arg.Threshold,
		arg.DurationMinutes,
		arg.ChannelIds,
	)
	return err
}
